import sys; sys.path.insert(0,'/home/claude/work/mahimna'); sys.path.insert(0,'/home/claude/work/bhaja')
from data1 import talk,svg,person,F
D=dict
B='#e3f2fd'
SUN=lambda x,y,r=14: f'<circle cx="{x}" cy="{y}" r="{r}" fill="#ffd60a" stroke="#ff8c1a" stroke-width="3"/>'
HILL='<path d="M0 130 L40 96 L80 112 L120 80 L160 104 L200 88 L220 100 V160 H0Z" fill="#2a7a4a" stroke="#111" stroke-width="2"/>'
TEMPLE=lambda x,y,s=1: f'<g transform="translate({x} {y}) scale({s})" stroke="#111" stroke-width="2"><rect x="-20" y="-20" width="40" height="20" fill="#ffd60a"/><path d="M-14 -20 l14 -24 l14 24z" fill="#e0a800"/></g>'
V=[
D(n='1–2',ids='1',lines=[['kausalyā suprajā rāma','pūrvā sandhyā pravartate |'],['uttiṣṭha naraśārdūla','kartavyaṃ daivamāhnikam ‖1‖'],['uttiṣṭhottiṣṭha govinda','uttiṣṭha garuḍadhvaja |'],['uttiṣṭha kamalākānta','trailokyaṃ maṅgalaṃ kuru ‖2‖']],theme='WAKE UP, O RĀMA; WAKE UP, GOVINDA',
 svg=svg('Dawn breaking over hills, with a sage calling to a young prince waking up, and a Garuda banner',HILL+SUN(170,96,16)+person(60,128,'#ff8c1a')+person(110,128,'#4a7fd0','#4a7fd0',.8)+'<path d="M150 40 v50" stroke="#111" stroke-width="3"/><path d="M150 40 h30 l-6 8 l6 8 h-30z" fill="#e63946" stroke="#111" stroke-width="1.5"/><text x="60" y="30" text-anchor="middle" '+F+' font-size="11">UTTIṢṬHA!</text>',B),
 mean='(1) O Rāma, blessed son of Kausalyā, the eastern dawn is breaking. Arise, O tiger among men: the day\'s sacred duties must be done. (2) Arise, arise, O Govinda! Arise, O Lord with Garuḍa on Your banner! Arise, O beloved of Kamalā, and make the three worlds auspicious.',
 plain='Wake up, Rāma: dawn is here and the day\'s duties await. Wake up, Govinda, Lord of Garuḍa, husband of Lakṣmī, and bless all the worlds.',
 words=[('kausalyā-suprajā','<b>good son of Kausalyā</b>'),('pūrvā sandhyā','the <b>eastern dawn</b>'),('uttiṣṭha','<b>arise!</b>'),('nara-śārdūla','<b>tiger among men</b>'),('garuḍa-dhvaja','<b>whose banner bears Garuḍa</b>'),('kamalā-kānta','<b>beloved of Kamalā</b> (Lakṣmī)')],
 deep='<p><b>From the Rāmāyaṇa.</b> Verse 1 is not by Aṇṇan at all: it is Viśvāmitra waking the young Rāma and Lakṣmaṇa in the forest, in the Bālakāṇḍa of Vālmīki\'s Rāmāyaṇa. The whole <i>suprabhāta</i> genre grows from this one verse.</p><p><b>From Rāma to Veṅkaṭeśa.</b> Verse 2 turns the same call to Govinda, the Lord of the Seven Hills. The tradition sees Śrīnivāsa as the same Viṣṇu who was Rāma and Kṛṣṇa.</p><p><b>Why wake God?</b> The Lord never sleeps; His "yoga-nidrā" is a loving fiction. Waking Him is really waking ourselves into the day with Him.</p>',
 cards=('💡 Viśvāmitra','The royal sage who took young Rāma to the forest and taught him divine weapons.','💡 Āhnika','The daily duties: morning prayer, sandhyā, worship.'),
 inner='Begin every day as if you were waking God, and you will find you have woken yourself.',
 talk=('The first verse is from the Rāmāyaṇa?','Yes! Viśvāmitra waking young Rāma. Every suprabhātam since has grown from that single morning call.'),
 key='"Kausalyā suprajā rāma": <b>a sage\'s morning call that became India\'s dawn prayer</b>.'),
D(n='3',lines=[['mātassamastajagatāṃ','madhukaiṭabhāreḥ'],['vakṣovihāriṇi','manoharadivyamūrte |'],['śrīsvāmini','śritajanapriyadānaśīle'],['śrīveṅkaṭeśadayite','tava suprabhātam ‖3‖']],theme='GOOD MORNING, MOTHER',
 svg=svg('Goddess Lakshmi seated on a lotus with a gentle smile, holding lotuses, light around her',SUN(110,40,26).replace('#ffd60a','#ffe9a0')+'<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="70" r="14" fill="#f2c79b"/><path d="M84 130 q26 -60 52 0z" fill="#e05a8a"/></g><path d="M70 140 q40 -20 80 0 q-40 16 -80 0z" fill="#f08aa6" stroke="#111" stroke-width="2"/><circle cx="80" cy="100" r="6" fill="#f08aa6" stroke="#111"/><circle cx="140" cy="100" r="6" fill="#f08aa6" stroke="#111"/><text x="110" y="156" text-anchor="middle" '+F+' font-size="10">PADMĀVATĪ · ŚRĪ</text>',B),
 mean='O Mother of all the worlds, who dwells on the chest of the slayer of Madhu and Kaiṭabha; O One of charming, divine form; O Queen, whose nature is to give lovingly to those who take refuge in You; O beloved of Śrī Veṅkaṭeśa: a good morning to You!',
 plain='Good morning, Mother Lakṣmī, who lives in Viṣṇu\'s heart, beautiful and generous to all who come to you, beloved of Veṅkaṭeśa.',
 words=[('mātaḥ','<b>O Mother</b>'),('madhu-kaiṭabha-ari','<b>enemy of Madhu and Kaiṭabha</b>: Viṣṇu'),('vakṣo-vihāriṇi','<b>who dwells on His chest</b>'),('śrīsvāmini','<b>O Queen</b>'),('śrita-jana-priya-dāna-śīle','<b>who loves to give to those who seek refuge</b>'),('dayite','<b>O beloved</b>')],
 deep='<p><b>Mother first.</b> Before waking the Lord, the hymn wakes the Goddess. In the Śrīvaiṣṇava tradition, Lakṣmī is the <b>puruṣakāra</b>, the one who recommends the devotee to the Lord: we approach Him through Her.</p><p><b>On His chest.</b> Lakṣmī lives on Viṣṇu\'s chest, the mark called Śrīvatsa. At Tirumala she is honoured as <b>Padmāvatī</b>, with her own temple at Tiruchanur below the hills.</p><p><b>Madhu and Kaiṭabha.</b> Two demons born from Viṣṇu\'s ears during His cosmic sleep, slain by Him: a fitting reference in a hymn about waking.</p>',
 cards=('💡 Puruṣakāra','"The one who intercedes": Lakṣmī\'s role in Śrīvaiṣṇava theology.','💡 Padmāvatī','Lakṣmī as the consort of Śrīnivāsa, worshipped at Tiruchanur.'),
 inner='Approach the Lord through the Mother: compassion opens the door that justice might keep shut.',
 talk=('Why wake the Goddess first?','In this tradition we go to the Lord through Lakṣmī. She is the mother who speaks for her children.'),
 key='First, good morning to <b>the Mother who speaks for us</b>.'),
D(n='4',lines=[['tava suprabhātam','aravindalocane'],['bhavatu prasanna-','mukhacandramaṇḍale |'],['vidhiśaṅkarendra-','vanitābhirarcite'],['vṛṣaśailanātha-','dayite dayānidhe ‖4‖']],theme='LOTUS-EYED, MOON-FACED',
 svg=svg('Three goddesses, Sarasvati, Parvati and Shachi, offering flowers to Lakshmi at dawn',SUN(180,30,12)+''.join(person(40+40*k,130,c,'#f2c79b',.7) for k,c in enumerate(['#fff','#e63946','#ffd60a']))+'<g stroke="#111" stroke-width="2.5"><circle cx="176" cy="96" r="12" fill="#f2c79b"/><path d="M156 140 q20 -46 40 0z" fill="#e05a8a"/></g><text x="80" y="160" text-anchor="middle" '+F+' font-size="8">SARASVATĪ · PĀRVATĪ · ŚACĪ</text>',B),
 mean='May it be a good morning for You, O lotus-eyed One, whose face is a serene full moon; who is worshipped by the wives of Brahmā, Śiva and Indra; beloved of the Lord of Vṛṣaśaila; O ocean of compassion.',
 plain='Good morning, lotus-eyed Lakṣmī, calm as the full moon, honoured by the goddesses, beloved of the Lord of the hills, ocean of kindness.',
 words=[('aravinda-locane','<b>O lotus-eyed</b>'),('prasanna-mukha-candra','<b>serene moon-face</b>'),('vidhi · śaṅkara · indra','<b>Brahmā</b> · <b>Śiva</b> · <b>Indra</b>'),('vanitābhiḥ arcite','<b>worshipped by their wives</b>'),('vṛṣaśaila-nātha','the <b>Lord of the bull-hill</b>'),('dayānidhe','<b>ocean of compassion</b>')],
 deep='<p><b>A different rhythm.</b> This verse is in a different metre from the rest, and it begins with the refrain the others end with: <i>tava suprabhātam</i>, "good morning to You".</p><p><b>The goddesses\' goddess.</b> Sarasvatī, Pārvatī and Śacī, the consorts of Brahmā, Śiva and Indra, come to worship Lakṣmī: she is honoured even by the other goddesses.</p><p><b>Vṛṣaśaila.</b> "The bull hill", one of the seven names of Tirumala (see verse 15).</p>',
 cards=('💡 Seven hills','Tirumala\'s seven peaks give Śrīnivāsa the name Saptagirīśa, "Lord of the seven hills".','💡 Dayā','Compassion: the quality the Śrīvaiṣṇava tradition most associates with Lakṣmī.'),
 inner='The one who is honoured by all is the one who is kind to all.',
 talk=('Other goddesses worship Lakṣmī?','In this verse, yes. Sarasvatī, Pārvatī and Indra\'s queen all come to her at dawn.'),
 key='Lotus-eyed, moon-faced, <b>an ocean of compassion</b>.'),
D(n='5',lines=[['atryādisaptaṛṣayas','samupāsya sandhyām'],['ākāśasindhukamalāni','manoharāṇi |'],['ādāya pādayugam','arcayituṃ prapannāḥ'],['śeṣādriśekharavibho','tava suprabhātam ‖5‖']],theme='THE SEVEN SAGES BRING LOTUSES',
 svg=svg('Seven sages walking up a hill carrying lotuses from a waterfall to the temple at the top',HILL+TEMPLE(180,84)+'<path d="M20 20 q4 40 0 80" stroke="#4aa3df" stroke-width="6" fill="none"/>'+''.join(person(40+18*k,130-6*k,'#ff8c1a','#f2c79b',.45) for k in range(7))+''.join(f'<circle cx="{46+18*k}" cy="{116-6*k}" r="3" fill="#f08aa6"/>' for k in range(7))+'<text x="40" y="18" '+F+' font-size="9">ĀKĀŚA GAṄGĀ</text>',B),
 mean='The seven sages led by Atri, having finished their twilight worship, have taken lovely lotuses from the heavenly river and come to worship Your two feet. O Lord who crowns the peak of Śeṣādri, a good morning to You!',
 plain='The seven great sages have done their morning prayers and brought lotuses from the sky-river to worship Your feet. Good morning, Lord of Śeṣādri!',
 words=[('atri-ādi-sapta-ṛṣayaḥ','<b>the seven sages led by Atri</b>'),('samupāsya sandhyām','<b>having performed sandhyā</b>'),('ākāśa-sindhu','the <b>sky-river</b>: Ākāśa Gaṅgā'),('pāda-yugam','<b>the two feet</b>'),('prapannāḥ','<b>have come, taken refuge</b>'),('śeṣādri-śekhara-vibho','<b>O Lord on the crest of Śeṣādri</b>')],
 deep='<p><b>The refrain begins.</b> From here every verse ends: <i>śeṣādri-śekhara-vibho tava suprabhātam</i>, "O Lord on the crest of Śeṣādri, a good morning to You!"</p><p><b>Two rivers.</b> <i>Ākāśa-sindhu</i> is the heavenly Gaṅgā; it is also the <b>Ākāśa Gaṅgā</b> waterfall near Tirumala, from which water is brought for the Lord\'s daily bath. The poet means both.</p><p><b>Śeṣādri.</b> The hill is said to be Ādiśeṣa, Viṣṇu\'s serpent, lying as the range; the Lord stands on its hood.</p>',
 cards=('💡 Saptarṣi','The seven sages: in one list Atri, Bhṛgu, Kutsa, Vasiṣṭha, Gautama, Kaśyapa, Aṅgiras.','💡 Ādiśeṣa','The cosmic serpent on whom Viṣṇu rests; the hills are its body.'),
 inner='Bring your best flowers, but finish your own prayers first.',
 talk=('Is Ākāśa Gaṅgā a real place?','Yes, a waterfall near the temple. Its water is still carried for the Lord\'s bath, and the poet plays on both meanings.'),
 key='The sages bring lotuses: <b>good morning, Lord of Śeṣādri</b>.'),
D(n='6',lines=[['pañcānanābjabhava-','ṣaṇmukhavāsavādyāḥ'],['traivikramādicaritaṃ','vibudhāḥ stuvanti |'],['bhāṣāpatiḥ paṭhati','vāsaraśuddhimārāt'],['śeṣādriśekharavibho','tava suprabhātam ‖6‖']],theme='THE GODS SING; THE ALMANAC IS READ',
 svg=svg('Gods with many faces praising, and Brihaspati reading an almanac scroll of the day',''.join(person(30+34*k,128,c,'#f2c79b',.6) for k,c in enumerate(['#bcd4f0','#e63946','#ffd60a','#2a9d6f']))+'<rect x="160" y="80" width="50" height="40" fill="#fff3b0" stroke="#111" stroke-width="2"/><text x="185" y="96" text-anchor="middle" '+F+' font-size="8">TITHI</text><text x="185" y="108" text-anchor="middle" '+F+' font-size="8">NAKṢATRA</text><text x="80" y="40" text-anchor="middle" '+F+' font-size="10">TRIVIKRAMA!</text>',B),
 mean='Śiva the five-faced, lotus-born Brahmā, six-faced Kārttikeya, Indra and the other gods praise Your deeds, such as Your three strides as Trivikrama; and close by, the lord of speech reads out the purity of the day. O Lord of Śeṣādri\'s crest, good morning!',
 plain='Śiva, Brahmā, Kārttikeya and Indra sing Your great deeds, like the three strides; Bṛhaspati reads the day\'s almanac nearby. Good morning, Lord!',
 words=[('pañcānana','<b>five-faced</b>: Śiva'),('abjabhava','<b>lotus-born</b>: Brahmā'),('ṣaṇmukha','<b>six-faced</b>: Kārttikeya'),('vāsava','<b>Indra</b>'),('traivikrama-carita','the <b>deed of the three strides</b>'),('vāsara-śuddhi','the <b>purity of the day</b>: the almanac')],
 deep='<p><b>All the gods.</b> Śiva, Brahmā, Kārttikeya and Indra stand at the Lord\'s door praising Him. The hymn is generous: other gods are not rivals but courtiers at His dawn.</p><p><b>Trivikrama.</b> Viṣṇu as Vāmana, the dwarf who grew and measured the worlds in three steps.</p><p><b>The pañcāṅga.</b> <i>Vāsara-śuddhi</i>: Bṛhaspati, "lord of speech", reads out the day\'s details, tithi, vāra, nakṣatra, yoga and karaṇa, just as the temple priests still read the almanac to the Lord each morning at Tirumala.</p>',
 cards=('💡 Pañcāṅga','The Hindu almanac with five limbs: tithi, vāra, nakṣatra, yoga, karaṇa.','💡 Trivikrama','Viṣṇu\'s form of the three strides, after the Vāmana avatāra.'),
 inner='Every day is worth announcing: know what day it is, and offer it.',
 talk=('Why read an almanac to God?','It\'s like a king being told the day\'s news. At Tirumala the pañcāṅgam is still read to the Lord after the Suprabhātam.'),
 key='The gods sing, the day is announced: <b>good morning, Lord</b>.'),
D(n='7',lines=[['īṣatpraphullasarasīruha-','nārikela-'],['pūgadrumādisumanohara-','pālikānām |'],['āvāti mandamanilaḥ','saha divyagandhaiḥ'],['śeṣādriśekharavibho','tava suprabhātam ‖7‖']],theme='THE MORNING BREEZE',
 svg=svg('Half-open lotuses, coconut and areca palms swaying, with curved lines of a gentle fragrant breeze',
  '<rect x="0" y="120" width="220" height="40" fill="#9fd3f0"/>'+''.join(f'<path d="M{x} 124 q-8 -14 0 -20 q8 6 0 20z" fill="#f08aa6" stroke="#111"/>' for x in (40,70,100))+'<path d="M160 120 v-80" stroke="#7a5a3a" stroke-width="5"/><path d="M160 40 q-20 -6 -30 10 M160 40 q20 -6 30 10 M160 40 q-10 -18 -24 -18 M160 40 q10 -18 24 -18" fill="none" stroke="#2a9d6f" stroke-width="4"/>'+''.join(f'<path d="M{20+30*k} {60+8*k} q14 -8 28 0" fill="none" stroke="#7fc4ef" stroke-width="2"/>' for k in range(4)),B),
 mean='From the gardens of half-opened lotuses, coconut and areca palms and other lovely trees, a gentle breeze is blowing with heavenly fragrances. O Lord of Śeṣādri\'s crest, good morning!',
 plain='A gentle breeze drifts in from the lotus pools and coconut groves, carrying sweet scents. Good morning, Lord!',
 words=[('īṣat-praphulla','<b>slightly opened</b>'),('sarasīruha','<b>lotus</b> (born in a lake)'),('nārikela · pūga','<b>coconut</b> · <b>areca</b>'),('pālikā','<b>rows, groves</b>'),('mandam anilaḥ','<b>a gentle breeze</b>'),('divya-gandhaiḥ','<b>with heavenly fragrances</b>')],
 deep='<p><b>Nature joins in.</b> From verse 7 to 12, the whole of nature wakes up to greet the Lord: breeze, birds, bees, cowherd homes, drums.</p><p><b>Half-open.</b> <i>Īṣat-praphulla</i>, "slightly opened": lotuses open with the sun, so at dawn they are only half-open. The poet catches the exact moment.</p><p><b>Temple gardens.</b> Tirumala\'s groves of coconut and areca, and its lotus tanks, are part of the scene: this is a real place described lovingly.</p>',
 cards=('💡 Sarasīruha','"Born in a lake": one of many Sanskrit words for lotus.','💡 Malaya breeze','Indian poetry loves the gentle, fragrant southern breeze of dawn.'),
 inner='Notice the morning: the breeze, the flowers, the light. Worship can begin with attention.',
 talk=('Even the breeze says good morning?','In this hymn, everything does: the wind, the flowers, the birds. The whole world wakes for Him.'),
 key='The fragrant breeze of dawn <b>wakes the Lord too</b>.'),
D(n='8',lines=[['unmīlya netrayugam','uttamapañjarasthāḥ'],['pātrāvaśiṣṭakadalī-','phalapāyasāni |'],['bhuktvā salīlamatha','keliśukāḥ paṭhanti'],['śeṣādriśekharavibho','tava suprabhātam ‖8‖']],theme='THE PARROTS RECITE',
 svg=svg('Green parrots in ornate cages, eating bananas and sweet rice from bowls, then reciting',
  ''.join(f'<g transform="translate({60+100*k} 60)"><path d="M-30 60 v-50 q30 -40 60 0 v50z" fill="none" stroke="#c9a26b" stroke-width="3"/><ellipse cx="0" cy="34" rx="12" ry="18" fill="#2a9d6f" stroke="#111" stroke-width="2"/><circle cx="0" cy="14" r="8" fill="#2a9d6f" stroke="#111" stroke-width="2"/><path d="M6 14 l8 4 l-8 2z" fill="#e63946"/></g>' for k in (0,1))+'<path d="M90 140 h40 l-6 10 h-28z" fill="#fff" stroke="#111" stroke-width="2"/><path d="M96 138 q10 -14 20 0" fill="#ffd60a" stroke="#111"/><text x="110" y="24" text-anchor="middle" '+F+' font-size="11">ŚRĪNIVĀSA! ŚRĪNIVĀSA!</text>',B),
 mean='Opening both their eyes, the pet parrots in their fine cages playfully eat the bananas and sweet rice left in their bowls, and then begin to recite. O Lord of Śeṣādri\'s crest, good morning!',
 plain='The pet parrots wake up, nibble the leftover bananas and pāyasam, and start chanting Your names. Good morning, Lord!',
 words=[('unmīlya','<b>opening</b> (the eyes)'),('pañjara-sthāḥ','<b>in cages</b>'),('pātra-avaśiṣṭa','<b>left in the bowls</b>'),('kadalī-phala','<b>bananas</b>'),('pāyasa','<b>sweet rice pudding</b>'),('keli-śukāḥ','<b>pet parrots</b>')],
 deep='<p><b>A homely scene.</b> Parrots were kept in temples and palaces and taught to repeat sacred names. The poet shows them waking, having breakfast, and starting to "chant".</p><p><b>Prasāda.</b> The bananas and pāyasam are left over from the previous night\'s offerings: even the parrots eat the Lord\'s prasāda.</p><p><b>Śuka.</b> The parrot is also the sage Śuka, who recited the Bhāgavatam: a gentle hint that every voice, even a bird\'s, can praise God.</p>',
 cards=('💡 Prasāda','Food offered to the Lord and then shared as a blessing.','💡 Śuka','The parrot-named sage who recited the Bhāgavata Purāṇa to King Parīkṣit.'),
 inner='Even a parrot that only repeats can praise God. Let your repetition become remembrance.',
 talk=('Parrots chanting?','Temple parrots really were taught names of God. Here they wake up, eat their pāyasam, and start their morning chant!'),
 key='Even the temple parrots <b>wake up chanting</b>.'),
D(n='9',lines=[['tantrīprakarṣamadhura-','svanayā vipañcyā'],['gāyatyanantacaritaṃ','tava nārado\'pi |'],['bhāṣāsamagramasakṛt-','karacāraramyaṃ'],['śeṣādriśekharavibho','tava suprabhātam ‖9‖']],theme='NĀRADA\'S VĪṆĀ',
 svg=svg('The sage Narada with a veena playing and singing, musical notes rising',
  '<g stroke="#111" stroke-width="2.5"><circle cx="90" cy="54" r="14" fill="#f2c79b"/><path d="M60 140 q30 -70 60 0z" fill="#ff8c1a"/><path d="M84 40 l6 -12 l6 12" fill="#fff"/></g><path d="M120 60 l60 80" stroke="#7a5a3a" stroke-width="5"/><circle cx="120" cy="56" r="10" fill="#c9a26b" stroke="#111" stroke-width="2"/><circle cx="182" cy="140" r="14" fill="#c9a26b" stroke="#111" stroke-width="2"/>'+''.join(f'<text x="{x}" y="{y}" '+F+f' font-size="18" fill="#1d6fb8">♪</text>' for x,y in [(150,40),(180,70),(40,40)]),B),
 mean='Even Nārada, on his vīṇā whose strings give out sweet, perfect notes, sings Your endless story, again and again, in flawless language, lovely with the movement of his hand. O Lord of Śeṣādri\'s crest, good morning!',
 plain='The sage Nārada plays his vīṇā and sings Your endless stories, beautifully, again and again. Good morning, Lord!',
 words=[('tantrī-prakarṣa','<b>excellence of strings</b>'),('madhura-svanayā','<b>with sweet sound</b>'),('vipañcī','a <b>vīṇā</b>'),('ananta-caritam','<b>endless deeds</b>, or the deeds of Ananta'),('bhāṣā-samagram','<b>perfect in language</b>'),('kara-cāra-ramyam','<b>lovely with the hand\'s movement</b>')],
 deep='<p><b>Nārada.</b> The wandering sage-musician, always singing "Nārāyaṇa", carrying news between the worlds. He is the model of devotion through music.</p><p><b>Music as worship.</b> Verse 8 had parrots reciting; verse 9 brings a master musician. From the simplest voice to the finest art, all praise the Lord.</p><p><b>Ananta.</b> <i>Ananta-carita</i> can mean "endless deeds" or "the deeds of the Endless One": both fit.</p>',
 cards=('💡 Nārada','The divine sage-musician, author of the Nārada Bhakti Sūtras.','💡 Vīṇā','India\'s classical stringed instrument; Nārada\'s is called Mahatī.'),
 inner='Use whatever gift you have, a voice, an instrument, a craft, as an offering.',
 talk=('Nārada is there too?','With his vīṇā, singing. The poet gathers every kind of praise: gods, sages, birds and bees.'),
 key='Nārada\'s vīṇā sings <b>the endless story of the Lord</b>.'),
D(n='10',lines=[['bhṛṅgāvalī ca','makarandarasānuviddhā'],['jhaṅkāragītaninadaiḥ','saha sevanāya |'],['niryātyupāntasarasī-','kamalodarebhyaḥ'],['śeṣādriśekharavibho','tava suprabhātam ‖10‖']],theme='THE BEES COME TO SERVE',
 svg=svg('Bees emerging from open lotuses in a pond, humming, flying toward a temple',
  '<rect x="0" y="120" width="220" height="40" fill="#9fd3f0"/>'+''.join(f'<path d="M{x} 124 q-12 -18 0 -26 q12 8 0 26z" fill="#f08aa6" stroke="#111"/>' for x in (40,80))+TEMPLE(186,100)+''.join(f'<g transform="translate({x} {y})"><ellipse rx="6" ry="4" fill="#ffd60a" stroke="#111"/><path d="M-2 -4 q-4 -8 -8 -2 M2 -4 q4 -8 8 -2" fill="none" stroke="#111"/></g>' for x,y in [(60,90),(90,70),(120,60),(150,70)])+'<text x="100" y="40" '+F+' font-size="11">JHAṄKĀRA!</text>',B),
 mean='Swarms of bees, steeped in the nectar of the flowers, come out from the hearts of the lotuses in the nearby lakes with their humming songs, to serve You. O Lord of Śeṣādri\'s crest, good morning!',
 plain='Bees full of nectar fly out of the lotuses humming, as if coming to serve You. Good morning, Lord!',
 words=[('bhṛṅga-āvalī','a <b>row of bees</b>'),('makaranda-rasa','<b>nectar</b>'),('anuviddhā','<b>steeped in</b>'),('jhaṅkāra','<b>humming</b>'),('sevanāya','<b>to serve</b>'),('kamala-udara','<b>the heart of the lotus</b>')],
 deep='<p><b>Trapped all night.</b> Poets love the idea that bees, caught inside lotuses when they close at dusk, are freed when the flowers open at dawn. So the bees\' appearance means sunrise.</p><p><b>Humming as song.</b> Their buzzing (<i>jhaṅkāra</i>) becomes a hymn, and their flight becomes service (<i>sevā</i>).</p><p><b>Sevā.</b> The word for service is the same used for the devotees\' darśan at Tirumala today: every visit is "sevā".</p>',
 cards=('💡 Sevā','Service, worship: at Tirumala, each ritual darśan is a sevā.','💡 Makaranda','Flower nectar: a favourite image of sweetness in devotional poetry.'),
 inner='Even our everyday hum of activity can become service, if we turn it toward the Lord.',
 talk=('The bees are serving God?','In the poet\'s eyes. They leave the lotuses humming at dawn, and he hears a hymn.'),
 key='Humming bees at dawn <b>come out to serve the Lord</b>.',
 note='Some texts read anuviddha for anuviddhā; the meaning is the same.'),
D(n='11',lines=[['yoṣāgaṇena varadadhni','vimathyamāne'],['ghoṣālayeṣu dadhi-','manthanatīvraghoṣāḥ |'],['roṣātkaliṃ vidadhate','kakubhaśca kumbhāḥ'],['śeṣādriśekharavibho','tava suprabhātam ‖11‖']],theme='CHURNING IN THE COWHERD HOMES',
 svg=svg('Women churning curd in large pots in cowherd houses at dawn, with loud churning sounds echoing',
  ''.join(f'<g transform="translate({50+80*k} 0)">'+person(0,130,'#e05a8a','#f2c79b',.7)+f'<ellipse cx="34" cy="132" rx="18" ry="16" fill="#c0703a" stroke="#111" stroke-width="2"/><path d="M34 70 v60" stroke="#7a5a3a" stroke-width="3"/><path d="M24 80 h20" stroke="#111"/></g>' for k in (0,1))+'<text x="110" y="40" text-anchor="middle" '+F+' font-size="13" fill="#c0392b">GHARR! GHARR!</text>',B),
 mean='As groups of women churn the fine curd in the cowherd homes, the loud sound of the churning seems to make the pots quarrel in anger with the directions, which echo it back. O Lord of Śeṣādri\'s crest, good morning!',
 plain='In the cowherd homes the women are churning curd, and the noise is so loud the pots seem to argue with the echoing hills. Good morning, Lord!',
 words=[('yoṣā-gaṇa','<b>groups of women</b>'),('vara-dadhni','<b>the excellent curd</b>'),('vimathyamāne','<b>being churned</b>'),('ghoṣa-ālaya','<b>cowherd homes</b>'),('tīvra-ghoṣāḥ','<b>loud sounds</b>'),('kakubhaḥ','the <b>directions</b>, the quarters')],
 deep='<p><b>A Gokula morning.</b> The scene is straight out of Kṛṣṇa\'s Vṛndāvana: gopīs churning butter at dawn. The poet brings that world to Tirumala.</p><p><b>A playful image.</b> The pots make so much noise that the four directions shout back: the echo becomes an argument. A little comedy in the middle of prayer.</p><p><b>Śrīvaiṣṇava sources.</b> Āṇḍāḷ\'s Tiruppāvai has a similar dawn verse about churning in the cowherd village: the hymn draws on the Tamil Āḻvārs.</p>',
 cards=('💡 Ghoṣa','Both "cowherd village" and "loud sound": the poet plays on the word.','💡 Tiruppāvai','Āṇḍāḷ\'s Tamil dawn songs, a key inspiration for this Suprabhātam.'),
 inner='Ordinary work done at dawn, churning, cooking, sweeping, is part of the world waking to God.',
 talk=('Why mention butter churning?','It\'s Kṛṣṇa\'s world, the cowherd village. And the noise is so loud the hills echo back as if arguing!'),
 key='The clatter of churning <b>is part of the Lord\'s morning music</b>.'),
D(n='12',lines=[['padmeśamitraśatapatra-','gatālivargāḥ'],['hartuṃ śriyaṃ kuvalayasya','nijāṅgalakṣmyā |'],['bherīninādamiva','bibhrati tīvranādaṃ'],['śeṣādriśekharavibho','tava suprabhātam ‖12‖']],theme='BEES LIKE DRUMS',
 svg=svg('Dark bees crowding in lotuses that open to the sun, their humming shown like the beat of a drum',
  SUN(180,40,16)+'<rect x="0" y="120" width="220" height="40" fill="#9fd3f0"/>'+''.join(f'<path d="M{x} 124 q-14 -20 0 -30 q14 10 0 30z" fill="#f08aa6" stroke="#111"/><circle cx="{x}" cy="104" r="5" fill="#222"/>' for x in (40,80,120))+'<g transform="translate(170 110)"><ellipse rx="22" ry="14" fill="#c0703a" stroke="#111" stroke-width="2"/><path d="M-22 0 h44" stroke="#111"/></g><text x="80" y="60" '+F+' font-size="12">DUM! DUM!</text>',B),
 mean='The swarms of bees in the lotuses, friends of the sun, make a loud sound like the beating of drums, as if, with the dark beauty of their own bodies, they mean to steal the beauty of the blue lily. O Lord of Śeṣādri\'s crest, good morning!',
 plain='Dark bees in the sun-opened lotuses buzz as loudly as drums, as if competing with the dark blue lilies in beauty. Good morning, Lord!',
 words=[('padmeśa','the <b>lord of lotuses</b>: the sun'),('śatapatra','a <b>hundred-petalled lotus</b>'),('ali-vargāḥ','<b>swarms of bees</b>'),('kuvalaya','the <b>blue lily</b>'),('nija-aṅga-lakṣmyā','<b>by the beauty of their own bodies</b>'),('bherī-nināda','the <b>sound of drums</b>')],
 deep='<p><b>A riddle of beauty.</b> The bees are dark; the blue lily (kuvalaya) is dark too. The poet imagines the bees jealous, beating drums as if going to war to steal the lily\'s beauty.</p><p><b>Sun and lotus.</b> The sun is called <i>padmeśa</i>, "lord of the lotus", because lotuses open at sunrise. So the bees sit in the sun\'s "friends".</p><p><b>Temple drums.</b> The bees\' "drums" echo the real drums (<i>bherī</i>) of the temple at dawn.</p>',
 cards=('💡 Kuvalaya','The blue water-lily, which opens at night and closes at dawn.','💡 Bherī','A large temple kettle-drum, beaten at dawn rituals.'),
 inner='Nature is full of small dramas. A poet sees them, and turns them into praise.',
 talk=('Bees beating drums?','Their buzzing is so loud it sounds like the temple drums. The poet makes it a little battle of beauty with the lilies.'),
 key='Bees drum at dawn: <b>even nature\'s little rivalries praise Him</b>.'),
D(n='13',lines=[['śrīmannabhīṣṭavarada-','akhilalokabandho'],['śrīśrīnivāsa jagad-','ekadayaikasindho |'],['śrīdevatāgṛhabhujāntara-','divyamūrte'],['śrīveṅkaṭācalapate','tava suprabhātam ‖13‖']],theme='ŚRĪNIVĀSA, FRIEND OF ALL',
 svg=svg('Lord Venkateswara standing with a broad chest where Lakshmi dwells, one hand granting boons, surrounded by light',
  SUN(110,60,40).replace('#ffd60a','#ffe9a0')+'<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="50" r="14" fill="#4a7fd0"/><path d="M96 34 h28 v-14 h-28z" fill="#ffd60a"/><path d="M84 150 q-4 -60 26 -84 q30 24 26 84z" fill="#ffd60a"/></g><path d="M100 30 h20" stroke="#fff" stroke-width="3"/><circle cx="104" cy="96" r="5" fill="#e05a8a"/><text x="110" y="156" text-anchor="middle" '+F+' font-size="10">ŚRĪNIVĀSA</text>',B),
 mean='O glorious One who grants every wish, friend of all the worlds! O Śrī Śrīnivāsa, the one ocean of compassion for the whole world! O One of divine form, whose chest is the home of the goddess Śrī! O Lord of Veṅkaṭācala, good morning!',
 plain='Lord who grants every wish, friend of the whole world, ocean of mercy, with Lakṣmī living in Your heart: good morning, Lord of the Veṅkaṭa hill!',
 words=[('abhīṣṭa-varada','<b>granting desired boons</b>'),('akhila-loka-bandho','<b>friend of all worlds</b>'),('śrīnivāsa','"<b>abode of Śrī</b>"'),('dayā-eka-sindho','<b>sole ocean of compassion</b>'),('śrī-devatā-gṛha','<b>home of the goddess Śrī</b>'),('bhuja-antara','<b>between the arms</b>: the chest')],
 deep='<p><b>A new refrain.</b> From here to verse 29, every verse ends: <i>śrī-veṅkaṭācala-pate tava suprabhātam</i>, "O Lord of the Veṅkaṭa hill, good morning".</p><p><b>Śrīnivāsa.</b> The Lord\'s best-loved name: "the dwelling of Śrī". Lakṣmī lives on His chest; so the Lord and the Goddess are never apart, a central point of Śrīvaiṣṇava faith.</p><p><b>Friend of all.</b> <i>Akhila-loka-bandhu</i>: not only of the pious; the verse sets no conditions.</p>',
 cards=('💡 Śrīnivāsa','"Abode of Śrī": the Lord of Tirumala, also Veṅkaṭeśvara, Bālājī, Govinda.','💡 Vyūha Lakṣmī','At Tirumala Lakṣmī is worshipped on the image\'s chest.'),
 inner='The Lord who keeps Lakṣmī in His heart keeps us there too.',
 talk=('Why is He called Śrīnivāsa?','Because Śrī, Lakṣmī, lives on His chest. Where He is, she is: grace and power together.'),
 key='Śrīnivāsa: <b>Lakṣmī\'s home, the friend of all</b>.'),
D(n='14',lines=[['śrīsvāmipuṣkariṇikā-','plavanirmalāṅgāḥ'],['śreyorthino haraviriñci-','sanandanādyāḥ |'],['dvāre vasanti','varavetrahatottamāṅgāḥ'],['śrīveṅkaṭācalapate','tava suprabhātam ‖14‖']],theme='THE GODS WAIT AT THE DOOR',
 svg=svg('Gods and sages waiting in a crowd at a golden temple door after bathing in a holy tank, with gatekeepers holding canes',
  '<rect x="0" y="130" width="80" height="30" fill="#4aa3df" stroke="#111" stroke-width="2"/><text x="40" y="150" text-anchor="middle" '+F+' font-size="8" fill="#fff">PUṢKARIṆĪ</text><rect x="150" y="40" width="60" height="100" fill="#ffd60a" stroke="#111" stroke-width="3"/><path d="M180 40 v100" stroke="#111"/>'+''.join(person(90+16*k,132,c,'#f2c79b',.5) for k,c in enumerate(['#bcd4f0','#e63946','#ff8c1a']))+'<path d="M146 60 l-20 30" stroke="#7a5a3a" stroke-width="3"/><text x="180" y="30" text-anchor="middle" '+F+' font-size="9">GOLDEN DOOR</text>',B),
 mean='Śiva, Brahmā, Sanandana and others, seeking the highest good, their bodies made pure by bathing in the Svāmi Puṣkariṇī, wait at Your door, their heads struck by the canes of the gatekeepers. O Lord of Veṅkaṭācala, good morning!',
 plain='Even Śiva, Brahmā and the great sages bathe in the temple tank and wait at Your door, jostled by the guards like any crowd. Good morning, Lord!',
 words=[('svāmi-puṣkariṇī','the <b>Lord\'s temple tank</b> at Tirumala'),('plava-nirmala-aṅgāḥ','<b>bodies pure from bathing</b>'),('śreyo-arthinaḥ','<b>seeking the highest good</b>'),('hara · viriñci','<b>Śiva</b> · <b>Brahmā</b>'),('dvāre vasanti','<b>wait at the door</b>'),('vetra-hata','<b>struck by canes</b>')],
 deep='<p><b>A Tirumala crowd.</b> Anyone who has queued at Tirumala recognises this: devotees bathe in the Svāmi Puṣkariṇī, then wait at the golden door, pressed by the crowd and the guards. The poet says even the gods have to wait.</p><p><b>Humour and humility.</b> Śiva and Brahmā being tapped on the head by the doorkeepers\' canes is affectionately comic: before the Lord, all are equal devotees.</p><p><b>The golden door.</b> The Suprabhātam is still recited every morning before the <b>bangāru vākili</b>, the golden door of the sanctum.</p>',
 cards=('💡 Svāmi Puṣkariṇī','The sacred tank beside the temple at Tirumala.','💡 Bangāru vākili','"Golden door": the entrance to the sanctum where the Suprabhātam is sung.'),
 inner='Before the Lord, no one is too great to wait in line.',
 talk=('The gods get hit by the guards\' sticks?','In the poem, yes, like everyone in the crowd. It\'s a lovely joke: at His door, all are just devotees.'),
 key='Even the gods <b>queue at His golden door</b>.',
 note='Some texts read haraviriñca for haraviriñci.'),
D(n='15',lines=[['śrīśeṣaśailagaruḍācala-','veṅkaṭādri-'],['nārāyaṇādrivṛṣabhādri-','vṛṣādrimukhyām |'],['ākhyāṃ tvadīyavasater','aniśaṃ vadanti'],['śrīveṅkaṭācalapate','tava suprabhātam ‖15‖']],theme='THE NAMES OF THE SEVEN HILLS',
 svg=svg('Seven hill peaks in a row, each labelled with its name, with the temple on top of one',
  ''.join(f'<path d="M{8+30*k} 140 l15 -{40+(k%3)*14} l15 {40+(k%3)*14}z" fill="#2a7a4a" stroke="#111" stroke-width="2"/><text x="{23+30*k}" y="154" text-anchor="middle" {F} font-size="6">{t}</text>' for k,t in enumerate(['ŚEṢA','GARUḌA','VEṄKAṬA','NĀRĀYAṆA','VṚṢABHA','VṚṢA','AÑJANA']))+TEMPLE(83,86,.6)+'<text x="110" y="26" text-anchor="middle" '+F+' font-size="11">SAPTAGIRI</text>',B),
 mean='Śeṣaśaila, Garuḍācala, Veṅkaṭādri, Nārāyaṇādri, Vṛṣabhādri, Vṛṣādri and the rest: these are the names by which people always speak of Your dwelling. O Lord of Veṅkaṭācala, good morning!',
 plain='Your hill has many names: Śeṣa, Garuḍa, Veṅkaṭa, Nārāyaṇa, Vṛṣabha, Vṛṣa and more. People speak them always. Good morning, Lord!',
 words=[('śeṣa-śaila','<b>Śeṣa\'s hill</b>'),('garuḍa-acala','<b>Garuḍa\'s hill</b>'),('veṅkaṭa-adri','<b>Veṅkaṭa hill</b>'),('nārāyaṇa-adri','<b>Nārāyaṇa\'s hill</b>'),('vṛṣabha · vṛṣa','<b>bull hills</b>'),('aniśam vadanti','<b>speak always</b>')],
 deep='<p><b>The seven hills.</b> Tirumala is called <b>Saptagiri</b>, "seven hills". Traditional lists name Śeṣādri, Nīlādri, Garuḍādri, Añjanādri, Vṛṣabhādri, Nārāyaṇādri and Veṅkaṭādri; the verse names six and adds "and the rest".</p><p><b>Each a story.</b> Śeṣa: Ādiśeṣa, Viṣṇu\'s serpent; Garuḍa: His eagle; Añjana: where Hanumān\'s mother did penance; Vṛṣabha: a demon devotee; Nārāyaṇa: where a sage did penance; Veṅkaṭa: "the hill that burns away sin", one explanation of the name.</p><p><b>Speaking the names.</b> Just saying the hill\'s names is itself praise.</p>',
 cards=('💡 Saptagiri','"Seven hills": Tirumala\'s peaks; Śrīnivāsa is Saptagirīśa.','💡 Veṅkaṭa','Often explained as "vem" (sin) + "kaṭa" (burning): the hill that destroys sin.'),
 inner='Even the names of holy places carry blessing. Say them with love.',
 talk=('Seven hills, but six names?','The verse ends "and the rest". Most lists include Nīlādri and Añjanādri too: seven in all.'),
 key='Śeṣa, Garuḍa, Veṅkaṭa…: <b>the seven hills of the Lord</b>.',
 note='Lists of the seven hills vary slightly between sources.'),
]
